function HandCardPlayer:OnChapterStart(generalVo, exParameter)
    -- 根据玩家性别，选择使用男女指挥官的手臂，并把animator绑定进timeline的轨道
    local go = self.controller.gameObject
    local goName = CfUtils.IsWoman() and "100_handcard_f" or "100_handcard_m"
    local hand = go.transform:Find(goName)
    local animator
    if hand then
        KTool.SetActive(hand, true)
        animator = hand:GetComponent(typeof(Animator))
    end
    if isNull(animator) then
        return
    end

    local pds = go:GetComponentsInChildren(typeof(PlayableDirector), true)
    local length = pds.Length
    for i = 0, length - 1, 1 do
        local pd = pds[i]
        local bindList = support.new_list(typeof(CS.UnityEngine.Playables.PlayableBinding))
        bindList:AddRange(pd.playableAsset.outputs)
        for i = 0, bindList.Count - 1 do
            local bind = bindList[i]
            if bind.streamName == "Handcard" then
                pd:SetGenericBinding(bind.sourceObject, animator)
            end
        end
    end
end

return HandCardPlayer